    const dialog=document.createElement('dialog');dialog.className='character-share-dialog';dialog.setAttribute('aria-label','Review character snapshot');dialog.innerHTML=`<div class="panel-heading"><h2>Review character snapshot</h2><button class="text-button" data-share-close>Close ×</button></div><img data-share-image alt="Preview of the full character statistics and equipment snapshot"><div class="capture-actions"><button class="primary-button" data-share-copy>Copy PNG</button><button class="secondary-button" data-share-save>Save PNG</button></div><label>Caption<textarea data-share-caption maxlength="1000" rows="2"></textarea></label><label class="check-control"><input type="checkbox" data-share-confirm> I reviewed this image and want to upload it to my own wiki talk page.</label><button class="secondary-button" data-share-upload>Upload to my User_talk page</button><p data-share-status role="status"></p>`;document.body.append(dialog);
    const areaDialog=document.createElement('dialog');areaDialog.className='ocr-area-dialog';areaDialog.setAttribute('aria-labelledby','ocr-area-title');areaDialog.innerHTML=`<h2 id="ocr-area-title">Calibrate OCR area</h2><p data-area-source></p><p>Select the complete examine or Inventory/stat pane, including its heading. Keep it visible until an editable proposal appears. Drag over the pane, or enter its percentages below. Only this area will be read. The preview is the last frame from your selected source; it is never saved.</p><div class="ocr-area-stage" data-area-stage><img data-area-image alt="Last frame from the current capture source" draggable="false"><div class="ocr-area-selection" data-area-selection></div></div><form data-area-form><fieldset><legend>Area as a percentage of the full frame</legend><div class="ocr-area-fields">${[['x','Left'],['y','Top'],['width','Width'],['height','Height']].map(([key,label])=>`<label>${label} (%)<input data-area-percent="${key}" name="${key}" type="number" min="${key==='width'||key==='height'?'0.1':'0'}" max="100" step="0.1" required></label>`).join('')}</div></fieldset><p data-area-status role="status"></p><div class="capture-actions"><button class="primary-button" type="submit" data-area-save>Save area</button><button class="secondary-button" type="button" data-area-full>Full frame</button><button class="text-button" type="button" data-area-cancel>Cancel</button></div></form>`;document.body.append(areaDialog);
