        <details open><summary>Extracted fields — confirm before use</summary>${Object.entries(fields).map(([key,field])=>`<label class="contribution-field" data-field-key="${escape(key)}"><span>${escape(key)}${key==='knownLoot'?'<small>One item title per line</small>':''}</span>${['statLines','knownLoot'].includes(key)?`<textarea data-field-value data-array="true" rows="${key==='statLines'?7:4}">${escape(Array.isArray(field.value)?field.value.join('\n'):field.value)}</textarea>`:`<input data-field-value data-type="${typeof field.value}" ${Array.isArray(field.value)?'data-array="true"':''} value="${escape(Array.isArray(field.value)?field.value.join(', '):field.value)}">`}<span class="check-control"><input data-field-confirmed type="checkbox" ${field.confirmed?'checked':''}> Verified</span></label>`).join('')}</details>
