    function selectedSource(){return $('[data-capture-source]',settingsRoot).value;}
    async function chooseSources(){if(!capture)throw Error('Screen reading requires the desktop app.');const previous=selectedSource();sources=await capture.sources();$('[data-capture-source]',settingsRoot).innerHTML='<option value="">Choose a window or display</option>'+sources.map(source=>`<option value="${escape(source.id)}">${escape(source.name)} (${escape(source.type)})</option>`).join('');if(sources.some(s=>s.id===previous))$('[data-capture-source]',settingsRoot).value=previous;else{const games=sources.filter(s=>/EverQuest/i.test(s.name));if(games.length===1)$('[data-capture-source]',settingsRoot).value=games[0].id;}}
